using System.Collections.Generic;
using NUnit.Framework;
using Rapadura.Gameplay.Items;
using UnityEngine;

namespace Rapadura.Tests
{
    /// <summary>
    /// Every authored item in Resources/Items must ship with an icon. The icons are generated by
    /// <c>tools/icons/generate_item_icons.py</c> (flat/low-poly PNG + Sprite .meta with a stable GUID, linked
    /// into the .asset). A new item without one fails here: add a recipe to the script (or let the category
    /// fallback draw it) and run it again.
    /// </summary>
    public class ItemIconCoverageTests
    {
        /// <summary>Items allowed to have no icon, each with the reason. Keep it empty unless there is a real case.</summary>
        private static readonly Dictionary<string, string> Exceptions = new Dictionary<string, string>();

        [Test]
        public void EveryResourceItem_HasAnIcon()
        {
            ItemDefinition[] items = Resources.LoadAll<ItemDefinition>("Items");
            Assert.That(items, Is.Not.Empty, "no ItemDefinition found under Resources/Items");

            var missing = new List<string>();
            foreach (ItemDefinition item in items)
            {
                if (item == null || Exceptions.ContainsKey(item.ItemId))
                {
                    continue;
                }

                if (item.Icon == null)
                {
                    missing.Add($"{item.ItemId} ({item.name})");
                }
            }

            Assert.That(missing, Is.Empty,
                "items without icon — run `python tools/icons/generate_item_icons.py` (add a recipe for new ids)");
        }

        [Test]
        public void ItemIcons_AreSquareSprites()
        {
            var wrong = new List<string>();
            foreach (ItemDefinition item in Resources.LoadAll<ItemDefinition>("Items"))
            {
                if (item == null || item.Icon == null)
                {
                    continue;
                }

                Rect r = item.Icon.rect;
                if (r.width < 32f || !Mathf.Approximately(r.width, r.height))
                {
                    wrong.Add($"{item.ItemId}: {r.width}x{r.height}");
                }
            }

            Assert.That(wrong, Is.Empty, "item icons must be square sprites of at least 32 px");
        }
    }
}
